package com.zhibrary.book;
import org.springframework.data.jpa.repository.JpaRepository; import java.util.*;
public interface BookRepository extends JpaRepository<Book,Long>{Optional<Book> findByIsbn(String isbn); List<Book> findByTitleContainingIgnoreCaseOrIsbnContainingIgnoreCaseOrCategoryContainingIgnoreCaseOrAuthorContainingIgnoreCase(String title,String isbn,String category,String author); long countByStatus(BookStatus status); @org.springframework.data.jpa.repository.Lock(jakarta.persistence.LockModeType.PESSIMISTIC_WRITE) @org.springframework.data.jpa.repository.Query("select b from Book b where b.id = :id") Optional<Book> lockById(@org.springframework.data.repository.query.Param("id") Long id);}
